"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["59396"],{58500(e){e.exports=JSON.parse('{"id":"FIN-B3-NEW3","slug":"mid-cap-stock","term":"Mid-Cap Stock","also_known_as":[],"difficulty":"Advanced","definition":"A mid-cap stock is a share in a company whose market capitalization falls between that of small-cap and large-cap companies.","explanation":["Companies are commonly grouped by size, measured by market capitalization, the share price multiplied by the number of shares. Mid-cap companies sit in the middle of this range. The exact boundaries vary between markets and index providers and change over time as markets grow.","Mid-cap companies are often established businesses that have moved beyond the start-up stage but still have room to grow. Many are leaders in specialized niches or regional markets.","For example, a mid-cap company might be a manufacturer of specialist industrial equipment with a strong position in its niche and plans to expand internationally.","Mid-caps are often seen as offering a balance between the growth potential of small companies and the stability of large ones. They are generally more volatile than large-caps but less so than small-caps, and their shares are usually reasonably liquid. Many investors hold mid-caps through funds tracking mid-cap indices, as part of a diversified portfolio."],"note":"","total":1725,"prev":{"slug":"microfinance","term":"Microfinance"},"next":{"slug":"mid-year-convention","term":"Mid-Year Convention"}}')}}]);